var data = {lines:[
{"lineNum":"    1","line":"#!/usr/bin/env bash"},
{"lineNum":"    2","line":"# Regenerate the package-lock.json of each npm directory devtools.toml lists, or of the one named."},
{"lineNum":"    3","line":"#"},
{"lineNum":"    4","line":"# Two things this does that a plain `npm install` does not:"},
{"lineNum":"    5","line":"#"},
{"lineNum":"    6","line":"#  1. It installs inside a Linux container, matching CI and the images the frontends are built in,"},
{"lineNum":"    7","line":"#     so the lockfile records the native packages a Linux install needs. A lockfile written on"},
{"lineNum":"    8","line":"#     macOS pins darwin builds of native dependencies, and `npm ci` on Linux then has to resolve"},
{"lineNum":"    9","line":"#     them again."},
{"lineNum":"   10","line":"#  2. It rewrites every resolved URL to the public registry. On a network that proxies npm, the"},
{"lineNum":"   11","line":"#     lockfile otherwise records that proxy\'s hostname on every line."},
{"lineNum":"   12","line":"#"},
{"lineNum":"   13","line":"#   [npm]"},
{"lineNum":"   14","line":"#   dirs = [\"frontend\"]"},
{"lineNum":"   15","line":"#   node_image = \"node:24-alpine\"   # optional"},
{"lineNum":"   16","line":"#"},
{"lineNum":"   17","line":"# Each directory needs an .npmrc naming the public registry, which goes into the container so any"},
{"lineNum":"   18","line":"# other setting it carries applies; the registry this machine reaches is passed on the command line"},
{"lineNum":"   19","line":"# and overrides its registry line."},
{"lineNum":"   20","line":"#"},
{"lineNum":"   21","line":"# Usage: .devtools/bin/lockfile.sh [DIR]    (from the repository root; needs Docker)"},
{"lineNum":"   22","line":"#   DOCKER   the docker command (default: docker)"},
{"lineNum":"   23","line":"#   NPM      the npm command asked for the registry (default: npm)"},
{"lineNum":"   24","line":"set -euo pipefail","class":"lineCov","hits":"1","order":"277",},
{"lineNum":"   25","line":""},
{"lineNum":"   26","line":"here=\"$(dirname \"$0\")\"","class":"lineCov","hits":"1","order":"275",},
{"lineNum":"   27","line":"[ -f \"$here/check-lockfile.sh\" ] || {","class":"lineCov","hits":"1","order":"272",},
{"lineNum":"   28","line":"  echo \"lockfile: needs $here/check-lockfile.sh; add bin/check-lockfile.sh to [fetch] files\" >&2","class":"lineCov","hits":"1","order":"269",},
{"lineNum":"   29","line":"  exit 1","class":"lineCov","hits":"1","order":"267",},
{"lineNum":"   30","line":"}"},
{"lineNum":"   31","line":"docker=\"${DOCKER:-docker}\"","class":"lineCov","hits":"1","order":"265",},
{"lineNum":"   32","line":"npm=\"${NPM:-npm}\"","class":"lineCov","hits":"1","order":"264",},
{"lineNum":"   33","line":"public=\"https://registry.npmjs.org/\"","class":"lineCov","hits":"1","order":"262",},
{"lineNum":"   34","line":""},
{"lineNum":"   35","line":"if [ $# -gt 0 ]; then","class":"lineCov","hits":"1","order":"260",},
{"lineNum":"   36","line":"  dirs=(\"$1\")","class":"lineCov","hits":"1","order":"259",},
{"lineNum":"   37","line":"else"},
{"lineNum":"   38","line":"  config=$(python3 \"$here/devtools-config.py\" --shape list npm.dirs)","class":"lineCov","hits":"1","order":"258",},
{"lineNum":"   39","line":"  mapfile -t dirs <<< \"$config\"","class":"lineCov","hits":"1","order":"274",},
{"lineNum":"   40","line":"  if [ -z \"${dirs[0]}\" ]; then","class":"lineCov","hits":"1","order":"271",},
{"lineNum":"   41","line":"    echo \"lockfile: [npm] dirs in devtools.toml is empty\" >&2","class":"lineCov","hits":"1","order":"279",},
{"lineNum":"   42","line":"    exit 1","class":"lineCov","hits":"1","order":"280",},
{"lineNum":"   43","line":"  fi"},
{"lineNum":"   44","line":"fi"},
{"lineNum":"   45","line":"image=$(python3 \"$here/devtools-config.py\" --default node:24-alpine npm.node_image)","class":"lineCov","hits":"1","order":"281",},
{"lineNum":"   46","line":""},
{"lineNum":"   47","line":"# The registry npm reaches outside any project, whose .npmrc would name the public one."},
{"lineNum":"   48","line":"registry=$(cd / && \"$npm\" config get registry 2>/dev/null) || registry=\"\"","class":"lineCov","hits":"1","order":"282",},
{"lineNum":"   49","line":"if [ -z \"$registry\" ] || [ \"$registry\" = \"undefined\" ]; then","class":"lineCov","hits":"1","order":"283",},
{"lineNum":"   50","line":"  registry=\"$public\"","class":"lineCov","hits":"1","order":"284",},
{"lineNum":"   51","line":"fi"},
{"lineNum":"   52","line":"echo \"Installing through: $registry\"","class":"lineCov","hits":"1","order":"285",},
{"lineNum":"   53","line":"echo \"Recording:          $public\"","class":"lineCov","hits":"1","order":"278",},
{"lineNum":"   54","line":""},
{"lineNum":"   55","line":"for dir in \"${dirs[@]}\"; do","class":"lineCov","hits":"1","order":"276",},
{"lineNum":"   56","line":"  if [ ! -f \"$dir/package.json\" ] || [ ! -f \"$dir/.npmrc\" ]; then","class":"lineCov","hits":"1","order":"273",},
{"lineNum":"   57","line":"    echo \"lockfile: $dir needs a package.json and an .npmrc naming $public\" >&2","class":"lineCov","hits":"1","order":"270",},
{"lineNum":"   58","line":"    exit 1","class":"lineCov","hits":"1","order":"268",},
{"lineNum":"   59","line":"  fi"},
{"lineNum":"   60","line":"  abs=\"$(cd \"$dir\" && pwd)\"","class":"lineCov","hits":"1","order":"266",},
{"lineNum":"   61","line":"  # Written beside the lockfile under another name, so a failed install leaves the committed one."},
{"lineNum":"   62","line":"  new=\"$dir/package-lock.json.new\"","class":"lineCov","hits":"1","order":"263",},
{"lineNum":"   63","line":"  rm -f \"$new\"","class":"lineCov","hits":"1","order":"286",},
{"lineNum":"   64","line":"  \"$docker\" run --rm \\","class":"lineCov","hits":"1","order":"261",},
{"lineNum":"   65","line":"    -v \"$abs/package.json:/app/package.json:ro\" \\"},
{"lineNum":"   66","line":"    -v \"$abs/.npmrc:/app/.npmrc:ro\" \\"},
{"lineNum":"   67","line":"    -v \"$abs:/output\" \\"},
{"lineNum":"   68","line":"    -w /app \\"},
{"lineNum":"   69","line":"    \"$image\" \\"},
{"lineNum":"   70","line":"    sh -c \"npm install --registry=\'$registry\' --no-fund --no-audit --loglevel=error && cp package-lock.json /output/package-lock.json.new\" \\"},
{"lineNum":"   71","line":"    || { rm -f \"$new\"; exit 1; }"},
{"lineNum":"   72","line":""},
{"lineNum":"   73","line":"  # A proxied registry records URLs of the form https://<host>/<prefix>/api/npm/<repo>/<pkg>,"},
{"lineNum":"   74","line":"  # which the public registry\'s never take. The pattern is shaped around that path rather than"},
{"lineNum":"   75","line":"  # any particular hostname or product."},
{"lineNum":"   76","line":"  sed -E \'s|https://[^\"]+/api/npm/[^/]+/|\'\"$public\"\'|g\' \"$new\" > \"$new.tmp\"","class":"lineCov","hits":"1","order":"257",},
{"lineNum":"   77","line":"  rm -f \"$new\"","class":"lineCov","hits":"1","order":"256",},
{"lineNum":"   78","line":"  \"$here/check-lockfile.sh\" \"$new.tmp\" || { rm -f \"$new.tmp\"; exit 1; }","class":"lineCov","hits":"1","order":"255",},
{"lineNum":"   79","line":"  mv \"$new.tmp\" \"$dir/package-lock.json\"","class":"lineCov","hits":"1","order":"254",},
{"lineNum":"   80","line":"  echo \"lockfile: regenerated $dir/package-lock.json\"","class":"lineCov","hits":"1","order":"253",},
{"lineNum":"   81","line":"done"},
]};
